import ipaddress, json, random

def spell(rng, value, length):
    addr = ":".join("%x" % ((value >> (112 - 16*i)) & 0xFFFF) for i in range(8))
    form = rng.random()
    if form < 0.25:
        addr = str(ipaddress.IPv6Address(value))
    elif form < 0.35:
        addr = addr.upper()
    elif form < 0.45:
        # compress longest zero run manually
        best, cur, start, bestspan = "", "", 0, (0, 0)
        parts = [((value >> (112-16*i)) & 0xFFFF) for i in range(8)]
        i = 0
        while i < 8:
            if parts[i] == 0:
                j = i
                while j < 8 and parts[j] == 0: j += 1
                if j-i > bestspan[1]-bestspan[0]: bestspan = (i, j)
                i = j
            else: i += 1
        seg = [("%x" % p) for p in parts]
        if bestspan[1] > bestspan[0]:
            left = ":".join(seg[:bestspan[0]]); right = ":".join(seg[bestspan[1]:])
            addr = (left + "::" + right) if left and right else ("::" + right if left=="" else left+"::")
    host = 0
    if length < 128 and rng.random() < 0.3:
        host = rng.getrandbits(128 - length)
    return "%s/%d" % (addr, length), value | host if False else (value | host) & ((1<<128)-1)

def make_routes(rng, count, spread=None):
    routes = []
    for _ in range(count):
        if spread == "narrow":
            base = rng.choice([0, 1, 2, 0x20010db8000000000000000000000000])
            value = base | rng.getrandbits(40)
            length = rng.choice([0, 32, 40, 48, 64, 100, 126, 127, 128])
        else:
            value = rng.getrandbits(128)
            length = rng.randint(0, 128)
        text, raw = spell(rng, value, length)
        size = 1 << (128-length)
        routes.append((text, (raw//size)*size, length, rng.randint(0, 30)))
    return routes

def make_case(rng, max_routes=6, max_tx=3, max_bursts=4, narrow=True):
    routes = make_routes(rng, rng.randint(0, max_routes), "narrow" if narrow else None)
    initial = [[t, hop] for t, _s, _l, hop in routes]
    if rng.random() < 0.15:
        initial = []
    transactions = []
    for _ in range(rng.randint(0, max_tx)):
        tx = []
        for _ in range(rng.randint(0, 3)):
            if rng.random() < 0.5 or not routes:
                t, s, l, hop = rng.choice(routes) if routes else (None,)*4
                if t is None:
                    t2 = make_routes(rng, 1)[0]
                    tx.append(["set", t2[0], t2[3]])
                else:
                    tx.append(["set", t, hop])
            else:
                t, s, l, hop = rng.choice(routes)
                tx.append(["erase", t])
        transactions.append(tx)
    versions = len(transactions)
    bursts = []
    for _ in range(rng.randint(0, max_bursts)):
        addrs = []
        for _ in range(rng.randint(0, 6)):
            if routes and rng.random() < 0.6:
                _t, s, l, _h = rng.choice(routes)
                addrs.append("%032x" % (s + rng.getrandbits(128-l) if l < 128 else s))
            else:
                addrs.append("%032x" % rng.getrandbits(128))
        addrs = [str(ipaddress.IPv6Address(int(a, 16))) for a in addrs]
        bursts.append({"version": rng.randint(0, versions), "repeat": rng.randint(1, 50),
                       "addresses": addrs})
    hit = rng.randint(1, 8)
    return {"initial": initial, "transactions": transactions, "bursts": bursts,
            "cache_pages": rng.randint(0, 4),
            "costs": {"hit": hit, "miss": rng.randint(hit, 40),
                      "decode": [rng.randint(0, 4) for _ in range(3)]}}

def make_request(seed, count=1, **kw):
    rng = random.Random(seed)
    return {"cases": [make_case(rng, **kw) for _ in range(count)]}
